+package handler
+
+import (
+	"fmt"
+	"net/url"
+	"strconv"
+)
+
+const (
+	defaultLimit = 50
+	maxLimit     = 100
+)
+
+// ListOptions controls a list request.
+type ListOptions struct {
+	Offset int
+	Limit  int
+}
+
+// ListOption adjusts ListOptions and may reject the adjustment.
+type ListOption func(*ListOptions) error
+
+// WithOffset skips the first n items. Negative values are treated as zero.
+func WithOffset(n int) ListOption {
+	return func(o *ListOptions) error {
+		if n < 0 {
+			n = 0
+		}
+		o.Offset = n
+		return nil
+	}
+}
+
+// WithLimit returns at most n items.
+func WithLimit(n int) ListOption {
+	return func(o *ListOptions) error {
+		if n < 1 {
+			return fmt.Errorf("limit must be a positive integer")
+		}
+		o.Limit = n
+		return nil
+	}
+}
+
+// WithMaxLimit caps whatever limit was set before it.
+func WithMaxLimit(max int) ListOption {
+	return func(o *ListOptions) error {
+		if o.Limit > max {
+			o.Limit = max
+		}
+		return nil
+	}
+}
+
+// newListOptions applies opts in order over the defaults.
+func newListOptions(opts ...ListOption) (ListOptions, error) {
+	o := ListOptions{Offset: 0, Limit: defaultLimit}
+	for _, opt := range opts {
+		if err := opt(&o); err != nil {
+			return ListOptions{}, err
+		}
+	}
+	return o, nil
+}
+
+// listOptionsFromQuery translates query parameters into options.
+func listOptionsFromQuery(q url.Values) ([]ListOption, error) {
+	var opts []ListOption
+	if raw := q.Get("offset"); raw != "" {
+		n, err := strconv.Atoi(raw)
+		if err != nil {
+			return nil, fmt.Errorf("offset must be an integer")
+		}
+		opts = append(opts, WithOffset(n))
+	}
+	if raw := q.Get("limit"); raw != "" {
+		n, err := strconv.Atoi(raw)
+		if err != nil {
+			return nil, fmt.Errorf("limit must be an integer")
+		}
+		opts = append(opts, WithLimit(n))
+	}
+	return append(opts, WithMaxLimit(maxLimit)), nil
+}
